       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:tencentcloud-agentobs-sdk-dsh','tencentcloud-agentobs-sdk-dsh','TencentCloud','https://github.com/TencentCloud/tencentcloud-agentobs-sdk-dsh/blob/main/README.md',NULL,'model','tencentcloud-agentobs-sdk-dsh 是一个 DeepSeek Harness (DSH) 可观测插件，直接将 GenAI trace 数据上报到腾讯云日志服务 (CLS)。  它观察 DSH 原生的 session、agent loop、LLM stream 和 tool 生命周期，将其转换为 腾讯云AI Agent可观测规范的 5 层 span 层级模型（entry → agent → step → chat → tool），并通过 tencentcloud-cls-sdk-js 直接上报到 CLS，无需额外部署 OTLP 收集器或 sidecar。','将 DeepSeek Harness 的 GenAI 追踪数据直接上报到腾讯云日志服务，实现 AI 应用的可观测性。','tencentcloud-agentobs-sdk-dsh',NULL,'dsh plugin add github:TencentCloud/tencentcloud-agentobs-sdk-dsh','github',13,0,13000,'0.1.0','2026-08-26','2026-09-12T20:35:55.334Z','2026-09-12T20:35:55.334Z',0,NULL,'3b487520')
