INSERT INTO plugins (id,name,owner,url,repo,category,desc_en,desc_zh,npm,tarball,install_target,target_kind,
       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-review-checkout','dsh-review-checkout','Binaryinject','https://github.com/Binaryinject/dsh-review-checkout',NULL,'dev','Codex-style review of session file changes: one card per edit turn (click a file to jump into that turn), a review tab with switchable split/card views (persisted across restarts), sticky headers and turn-scoped syntax-highlighted diffs, a live pill/badge that follows the in-flight turn, 12 fully-wired color settings with light/dark presets that follow the DSH theme live, one-click per-turn revert via a built-in tool (works on DSH Desktop too) that fills the revert instruction into the composer, workspace-relative paths and a resilient multi-stage session-history fallback chain (cold-boot channel attach) for the current DSH session API.','Codex 风格的会话文件修改审查：每轮编辑一张卡片（点击文件跳转到该轮审查）；审查标签支持分屏/卡片双视图切换（选择在重启后保留）、按轮展示语法高亮 diff 且文件头吸顶；运行态胶囊/徽章跟随当前进行中的轮次（新轮次开始时不再显示上一轮变更，并即时刷新）；12 项完整生效的颜色设置与深浅双套预设，随 DSH 主题即时切换；内置工具按轮一键撤销（DSH Desktop 同样可用，撤销指令自动填入对话输入框）；工作区相对路径显示；多级回退的会话历史通道（含冷启动通道附加），兼容当前 DSH 会话 API。','dsh-review-checkout',NULL,'dsh plugin --profile web add dsh-review-checkout','npm',4,1103,5103,'0.7.3','2026-08-28','2026-09-12T20:35:55.334Z','2026-09-12T20:35:55.334Z',0,NULL,'256aca9a')
     ON CONFLICT(id) DO UPDATE SET stars=excluded.stars, downloads=excluded.downloads, score=excluded.score,
