INSERT INTO plugins (id,name,owner,url,repo,category,desc_en,desc_zh,npm,tarball,install_target,target_kind,
       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:@riceawa/dsh-lan-gateway','dsh-lan-gateway','rice-awa','https://github.com/rice-awa/dsh-lan-gateway',NULL,'notify','LAN/internet reverse-proxy gateway for the DeepSeek Harness web GUI: keeps dsh on loopback, exposes 0.0.0.0 with login + HMAC cookie for non-LAN sources (LAN and loopback are proxied without a password by default), optional self-signed or custom TLS, and a Settings card. Includes an insecure-origin UUID shim so workspaces open over plain-HTTP LAN addresses.','DeepSeek Harness Web GUI 的局域网/公网反向代理网关：dsh 仍绑定回环，本插件在 0.0.0.0 提供登录+HMAC Cookie（仅对非局域网来源生效，局域网与回环来源默认免密直连）、可选自签名或自定义 TLS 与官方设置页卡片。自带不安全源 UUID shim，让局域网纯 HTTP 地址也能正常打开工作区。','@riceawa/dsh-lan-gateway',NULL,'dsh plugin --profile web add @riceawa/dsh-lan-gateway','npm',4,614,4614,'0.4.0','2026-08-28','2026-09-12T20:35:55.334Z','2026-09-12T20:35:55.334Z',0,NULL,'b8e4f5f8')
