INSERT INTO plugins (id,name,owner,url,repo,category,desc_en,desc_zh,npm,tarball,install_target,target_kind,
       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:@feiyang666/dsh-vault','dsh-vault','feiyang-dev','https://github.com/feiyang-dev/dsh-vault',NULL,'desktop','DeepSeek Harness 数据保险箱插件（dsh-vault）—— 自动备份、清空检测、一键恢复，保护聊天记录与工作区数据；可经桌面端一键安装或命令行 dsh plugin add 安装。','数据保险箱：为 DeepSeek Harness 提供备份、清空检测与一键恢复。备份触发时机：启动备份、意外关闭备份、手动备份（不再按会话落盘或定时全量备份，避免大量任务运行时卡死）。自动备份 ~/.dsh 的聊天记录(sessions)、工作区数据(storages)、设置(settings.yaml)、凭据与 profile 配置到用户主目录 ~/.dsh-backups（最多保留 10 份），检测数据被清空并支持按范围恢复与删除备份。设置页提供「备份管理」界面（Host+Client 双面插件）。','@feiyang666/dsh-vault',NULL,'dsh plugin --profile web add @feiyang666/dsh-vault','npm',3,0,3000,'1.3.2','2026-08-23','2026-09-12T20:35:55.334Z','2026-09-12T20:35:55.334Z',0,NULL,'1d8bb125')
