       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-unified-market','dsh-unified-market','jing-hy','https://github.com/jing-hy/dsh-unified-market',NULL,'security','Unified plugin marketplace built for the DSH Desktop (EAC) shell, aggregating the curated catalog, the GitHub dsh-plugin ecosystem and the npm registry into one storefront, with source whitelisting, conflict pre-checks, trial-boot install verification, manual/batch/auto updates and .dshpack feature-pack management.','面向 DSH Desktop（EAC）桌面壳的统一插件市场：聚合精选目录、GitHub dsh-plugin 生态与 npm registry 三源，提供来源白名单、冲突预检、试装安装验证、手动/批量/自动三档更新与功能包（.dshpack）管理。','dsh-unified-market',NULL,'dsh plugin --profile web add dsh-unified-market','npm',2,804,2804,'0.4.0','2026-08-27','2026-09-12T20:35:55.334Z','2026-09-12T20:35:55.334Z',0,NULL,'c4213731')
