       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('npm:dsh-env-profile','dsh-env-profile','Yvesgao','https://github.com/Yvesgao/dsh-env-profile',NULL,'memory','DSH 全局经验插件：自动探测环境 + 跨会话档案 + 低开销注入，减少重复探测、加快会话、降低 token。','DSH 全局经验插件（骨架）：自动探测本地依赖/便捷路径/网络/磁盘并沉淀为跨会话环境档案，订阅 session/event 折叠每会话统计，把低开销摘要注入每轮系统提示，env_profile 工具按需查全量——减少重复探测、加快会话、降低 token 消耗。','dsh-env-profile',NULL,'dsh plugin --profile web add dsh-env-profile','npm',1,0,1000,'0.1.0','2026-08-30','2026-09-12T20:35:55.334Z','2026-09-12T20:35:55.334Z',0,NULL,'d13128f5')
