INSERT INTO plugins (id,name,owner,url,repo,category,desc_en,desc_zh,npm,tarball,install_target,target_kind,
       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('repo:mx1syk/dsh-x-opencode-session','dsh-x-opencode-session','MX1syk','https://github.com/MX1syk/dsh-x-opencode-session',NULL,'security','一个 DeepSeek Harness（DSH）插件，为 LLM provider 请求注入动态/随机的 HTTP 请求头。DSH 的 pi-ai provider 只支持静态 headers 字符串，无法表达动态值；本插件通过包装 globalThis.fetch，按 urlPatterns 匹配请求并注入 ${uuid} 等模板值（每个 DSH 进程铸造唯一且在进程内稳定的会话 id），解决 opencode-go 网关对 x-opencode-session 头的要求（缺失会返回 400 Model is unavailable）。零默认、卸载安全、日志自动脱敏凭据。','给 LLM 请求动态注入随机请求头，生成进程内稳定的会话 ID，解决静态配置无法表达动态值的问题。',NULL,NULL,'dsh plugin add github:MX1syk/dsh-x-opencode-session','github',0,0,0,'','2026-09-09','2026-09-12T20:35:55.334Z','2026-09-12T20:35:55.334Z',0,NULL,'ec7f7b8c')
