INSERT INTO plugins (id,name,owner,url,repo,category,desc_en,desc_zh,npm,tarball,install_target,target_kind,
       stars,downloads,score,version,added_at,first_seen,updated_at,deprecated,replacement,content_hash) VALUES ('repo:shengyvself/narrative-prompt-polish','narrative-prompt-polish','shengyvself','https://github.com/shengyvself/narrative-prompt-polish',NULL,'agent','One-click prompt polisher for the DSH composer: a ✨ button next to the message box opens a side-chat where an agent refines your rough draft over multiple turns, then you copy the result back. Replays the session prefix to hit the prompt cache, with a full → partial → none fallback for oversized or non-live sessions, per-call JSONL tracing, and a trust fence plus CAS write-back that refuses to overwrite a draft changed since the request. Requires omdsh-dev/DSH-better-sidebar (>=0.16.1); errors explicitly if it is missing rather than failing silently.','DSH 主输入框旁的 ✨ 一键提示词打磨：点击后在侧边对话中由 Agent 多轮改写草稿，再手动回填。复刻会话前缀以命中 prompt cache，超大或非 live 会话按 full → partial → none 降级；每次调用留 JSONL trace；API 路由带信任围栏，CAS 写回在草稿已变时拒绝覆盖。需先安装 omdsh-dev/DSH-better-sidebar（>=0.16.1），缺失时显式报错而非静默失效。',NULL,NULL,'dsh plugin --profile web add github:shengyvself/narrative-prompt-polish','github',0,0,0,'','2026-09-01','2026-09-12T20:35:55.334Z','2026-09-12T20:35:55.334Z',0,NULL,'e1693c5')
